def second_smallest(numbers):
    """
    Returns the second smallest number in the list.
    Raises a ValueError if there is no second smallest number.
    """
    if not isinstance(numbers, list):
        raise TypeError("Input must be a list.")
    if len(numbers) < 2:
        raise ValueError("List must contain at least two distinct elements.")

    first = second = None
    for num in numbers:
        if first is None or num < first:
            second = first
            first = num
        elif num != first and (second is None or num < second):
            second = num

    if second is None:
        raise ValueError("No second smallest element found (all elements might be equal).")
    return second


